import{_ as t}from"./chunks/model-link-setting-01.CpWihLl4.js";import{_ as a}from"./chunks/model-link-setting-02.2A_MOACW.js";import{_ as o}from"./chunks/model-setting-01.B6pLEcOa.js";import{_ as n,o as r,c as i,a3 as s}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"Model link and parameters","description":"MiniTavern BYOK model links — fill Base URL and API Key, test connection, sampling parameters; connect cloud or Ollama/LM Studio local OpenAI-compatible APIs.","frontmatter":{"title":"Model link and parameters","description":"MiniTavern BYOK model links — fill Base URL and API Key, test connection, sampling parameters; connect cloud or Ollama/LM Studio local OpenAI-compatible APIs.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Model link and parameters · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern BYOK model links — fill Base URL and API Key, test connection, sampling parameters; connect cloud or Ollama/LM Studio local OpenAI-compatible APIs."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/manual/model-link"}]]},"headers":[],"relativePath":"en/manual/model-link.md","filePath":"en/manual/model-link.md","lastUpdated":1787813788000}'),l={name:"en/manual/model-link.md"};function d(m,e,c,g,h,p){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="model-link-and-parameters" tabindex="-1">Model link and parameters <a class="header-anchor" href="#model-link-and-parameters" aria-label="Permalink to &quot;Model link and parameters&quot;">​</a></h1><p>BYOK: keys stay in on-device secure storage; requests go straight to the address you configure.</p><p>Without a paid API, start with <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a>; local deploy: <a href="/ultra_guides/en/local/">Run local models</a>.</p><h2 id="model-link" tabindex="-1">Model link <a class="header-anchor" href="#model-link" aria-label="Permalink to &quot;Model link&quot;">​</a></h2><p>Path: <strong>Settings → Models → Model link</strong></p><p><img src="'+t+'" alt="Model link list"></p><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td>New</td><td>Platform, key, Base URL, model</td></tr><tr><td>Edit / Copy / Delete</td><td>List overflow menu</td></tr><tr><td>Set as default</td><td>Used by new chats by default</td></tr><tr><td>Test</td><td>Before save or on the edit page. Must pick a <strong>text chat</strong> model; TTS / image-only IDs (e.g. Gemini <code>*-tts</code>) fail text chat — see <a href="./errors#textoutputunsupported">Errors · textOutputUnsupported</a></td></tr></tbody></table><h3 id="platform-types-common" tabindex="-1">Platform types (common) <a class="header-anchor" href="#platform-types-common" aria-label="Permalink to &quot;Platform types (common)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option (labels follow the App)</th><th>Use</th></tr></thead><tbody><tr><td>Vendor presets</td><td>Auto-fill China / international Base URL</td></tr><tr><td>Custom (OpenAI)</td><td>Local Ollama / LM Studio, compatible gateways</td></tr><tr><td>Custom Gemini / Anthropic</td><td>Matching protocol endpoints</td></tr></tbody></table><p>Multi-site platforms can switch “Use international site”. Local models: <a href="/ultra_guides/en/connect-app/minitavern">Connect MiniTavern</a> and <a href="/ultra_guides/en/local/tools">Tools overview</a>.</p><p><img src="'+a+'" alt="Create link"></p><h2 id="model-settings-global-parameters" tabindex="-1">Model settings (global parameters) <a class="header-anchor" href="#model-settings-global-parameters" aria-label="Permalink to &quot;Model settings (global parameters)&quot;">​</a></h2><p>Path: <strong>Settings → Model settings</strong></p><p><img src="'+o+'" alt="Model settings"></p><p>Common items (names follow the App):</p><ul><li>Memory length (related to history message count)</li><li>Reply tokens (max tokens, up to 128000; some Claude cases <strong>must not</strong> be None)</li><li>Temperature, Top-P / Top-K</li><li>Whether to stream output</li></ul><h2 id="per-chat-overrides" tabindex="-1">Per-chat overrides <a class="header-anchor" href="#per-chat-overrides" aria-label="Permalink to &quot;Per-chat overrides&quot;">​</a></h2><p>Path: conversation → <strong>Settings</strong> → Model link / parameters</p><p>You can set link and sampling for one chat without changing the global default.</p><h2 id="vision-in-chat-settings" tabindex="-1">Vision in chat settings <a class="header-anchor" href="#vision-in-chat-settings" aria-label="Permalink to &quot;Vision in chat settings&quot;">​</a></h2><p>Path: <strong>Settings → Chat → Vision settings</strong></p><p>Per chat, <strong>Chat settings → Vision &amp; display</strong> can follow defaults or override (caption model and prompts still use global).</p><ul><li>“Image caption” off: multimodal models receive the image directly (model must support vision).</li><li>On: only when the current chat’s main model <strong>does not</strong> support image parameters — a caption model first turns image→text (can share one request with face ID), then the main model runs; captions are cached. If the main model already supports vision, images still go multimodal; this switch does not block them.</li></ul><p>Send order when the main model lacks images and caption is on: caption (+ face ID) → main chat (if smart/keyword reply-image is on, may attach image-gen prompts) → if the reply carries image-gen data, side-path image gen.</p><p>If you see “current model does not support images”, see <a href="./errors#visionunsupported">Errors · visionUnsupported</a>.</p><h2 id="image-gen-link-reply-images-keywords" tabindex="-1">Image gen (link / reply images / keywords) <a class="header-anchor" href="#image-gen-link-reply-images-keywords" aria-label="Permalink to &quot;Image gen (link / reply images / keywords)&quot;">​</a></h2><p>Path: <strong>Settings → Image gen</strong></p><ul><li><strong>Image gen link / Image gen settings</strong>: API, size/quality, generation count (<code>/imagine</code> only), enhance/negative prompts (only <code>/imagine</code> and attachment-menu image gen; default quality words / low quality·blur·extra fingers·watermark, etc.)</li><li><strong>Reply images</strong> (in image gen settings): turn the switch on, then pick a trigger. When off, chat does not auto-generate images (slash commands, attachment menu, and long-press bubbles are unaffected) <ul><li><strong>Smart detect</strong>: the model decides whether this turn needs an image; aspect ratio follows the scene (phone selfie 3:4, camera shot 3:2); on hit, exactly 1 image. You can attach a reference (e.g. “draw in this style”); the attachment is style reference only, not character/user identity</li><li><strong>Keyword trigger</strong>: user message matches a keyword rule (attachments allowed); scene and aspect follow the chat; on hit, exactly 1 image</li></ul></li><li><strong>Keyword image triggers</strong>: configure rules. To actually fire, enable reply images in image gen settings and choose keyword trigger</li></ul><p>Image gen in chat:</p><table tabindex="0"><thead><tr><th>Entry</th><th>Description</th></tr></thead><tbody><tr><td><code>/imagine prompt</code></td><td>Main chat model first decides relevance and whether to use character/user refs, then builds the prompt and generates. Attachments via “+” are seen by the main model when writing the prompt and used as refs during gen; they do not skip character/user image decisions. Those images show as small previews on the image-gen bubble, not as a chat message. Count uses “Generation count” in image settings. On failure the bubble remains with retry</td></tr><tr><td><code>/imagine scene</code> / Attach → From story</td><td>Draw the current scene from recent dialogue, 1 image</td></tr><tr><td><code>/imagine last</code> / Attach → From last message</td><td>Draw from the last message, 1 image</td></tr><tr><td>Attach → Generate background</td><td>Draw an environment background, 1 image; then you can set it as chat background</td></tr><tr><td>Long-press bubble → Image gen</td><td>Draw from that bubble, 1 image</td></tr></tbody></table><p>Example: “Give me a selfie of you” uses character refs and chat context; “a photo of a puppy” is treated as a standalone request without the character’s face.</p><p>Local A1111 / ComfyUI: <a href="/ultra_guides/en/local/image-gen/">Image model deploy</a> · <a href="/ultra_guides/en/local/image-gen/connect-app">Connect App</a>.<br> Cloud free tiers: <a href="/ultra_guides/en/free-cloud/#free-image-generation">Free cloud · Image gen</a>.</p><p>When no image gen link is configured, the four attachment image modes and sending <code>/imagine</code> show “Go to settings / Cancel” without clearing the input. Smart / keyword auto image gen uses Toast. Enabling “Reply images” without a link shows a modal and keeps the switch off.</p><h2 id="troubleshooting-entry" tabindex="-1">Troubleshooting entry <a class="header-anchor" href="#troubleshooting-entry" aria-label="Permalink to &quot;Troubleshooting entry&quot;">​</a></h2><p>Test or chat failure → Toast / bubble → <strong>View details</strong> (error code + cause + suggestions) → <a href="./errors">Error codes</a>.</p>',35)])])}const w=n(l,[["render",d]]);export{k as __pageData,w as default};
